), eligible as (
 select e.id lexical_entry_id,e.strong_number,e.source_gloss,map.display_gloss_es,
        regexp_replace(split_part(e.source_gloss,'»',1),'^:\s*','') primary_en
 from public.biblical_lexical_entries e
 join map on map.primary_en=regexp_replace(split_part(e.source_gloss,'»',1),'^:\s*','')
 left join public.biblical_hebrew_spanish_glosses g on g.lexical_entry_id=e.id
 where e.language='hebrew' and e.enabled and e.review_status='approved' and e.part_of_speech='verb'
   and e.source_gloss like ':%' and e.display_gloss_es is null and g.lexical_entry_id is null
)
insert into public.biblical_hebrew_spanish_glosses
(lexical_entry_id,display_gloss_es,alternative_glosses_es,confidence,derivation_method,source_gloss_snapshot,status,provenance)
select lexical_entry_id,display_gloss_es,'{}'::text[],96,'manual_editorial_structured_primary_sense_v1',source_gloss,'manual_approved',
 jsonb_build_object('phase','FASE_H_BLOQUE_3','batch_id','fase_h_es_verbs_structured_editorial_001_20260820','source','STEPBible/TAHOT structured source_gloss en','source_license','CC BY 4.0','translation_layer','VIDA editorial Spanish','translation_basis','explicit primary sense before »; verb POS','context_used_as_meaning',false,'rv1909_used_as_meaning',false,'hebrew_lemma_used_to_infer_meaning',false,'strong_number',strong_number,'primary_sense_en',primary_en)
from eligible
on conflict (lexical_entry_id) do nothing;
